from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data.get('events', [])):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            key = ('id', event['id'])
        else:
            key = ('anonymous', position)

        revision = event.get('revision', 0)
        candidate = (revision, position, event)
        previous = winners.get(key)
        if previous is None or candidate[:2] >= previous[:2]:
            winners[key] = candidate

    balances = dict(data.get('opening', {}))
    rounding = data.get('rounding', 'half_up')

    for _, _, event in winners.values():
        if event.get('void', False):
            continue
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances.setdefault(key, 0)
        balances[key] += amount(event, rounding)

    return {'balances': balances}

def _round_ratio(numerator, denominator, mode):
    if mode == 'floor':
        return numerator // denominator
    return (2 * numerator + denominator) // (2 * denominator)


def amount(event, mode):
    gross = event['price'] * event.get('quantity', 1)
    discount_bp = min(10000, max(0, event.get('discount_bp', 0)))
    net = _round_ratio(gross * (10000 - discount_bp), 10000, mode)

    tax_bp = event.get('tax_bp', 0)
    tax = _round_ratio(net * tax_bp, 10000, mode)
    total = net + tax

    if event.get('kind') == 'refund':
        return -total
    return total
